// Only explicit current-source delivery assertions change; historical proofs remain exact.
import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261023-fda-review-website',site=stage+'/website',prep=json(stage+'/PREPARATION.json'),parent=json(prep.parentReceipt),cap=json(stage+'/CAPTURE.json'),rows=[];
assert.equal(cap.sourceFiles,1591);assert.equal(cap.inputs,1778);assert.equal(cap.viewerFiles,50);assert.equal(cap.viewerPackages,24);
function edit(path,edits){const original=fs.readFileSync(site+'/'+path,'utf8');let after=original;for(const[a,b,n=1]of edits){assert.equal(after.split(a).length-1,n,path);after=after.split(a).join(b);}let inverse=after;for(const[a,b,n=1]of [...edits].reverse()){assert.equal(inverse.split(b).length-1,n);inverse=inverse.split(b).join(a);}assert.equal(inverse,original);rows.push({path,beforeSha256:hash(site+'/'+path),afterSha256:createHash('sha256').update(after).digest('hex'),edits,wholeFileInverse:true,after});}
edit('tests/current-atlas-delivery.mjs',[["assert.equal(pin.viewerFiles,46);assert.equal(pin.viewerPackages,22);","assert.equal(pin.viewerFiles,50);assert.equal(pin.viewerPackages,24);"]]);
edit('tests/current-atlas-delivery.test.mjs',[[parent.atlasHead,prep.atlasHead,3],[parent.atlasTree,prep.atlasTree],['assert.equal(sourceFiles,1581);assert.equal(inputs,1750);','assert.equal(sourceFiles,1591);assert.equal(inputs,1778);']]);
edit('tests/regional-tour-entry-delivery.test.mjs',[['assert.equal(binding.inputs.length,1750);','assert.equal(binding.inputs.length,1778);']]);
edit('tests/compact-head-provenance.test.mjs',[["assert.equal(current.sourceCommit,'"+parent.atlasHead+"');","assert.equal(current.sourceCommit,'"+prep.atlasHead+"');"]]);
function diff(a,b){const left=a.trimEnd().split('\n'),right=b.trimEnd().split('\n'),n=left.length,m=right.length,dp=Array.from({length:n+1},()=>new Uint32Array(m+1));for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=left[i]===right[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);const ops=[];let i=0,j=0;while(i<n||j<m){if(i<n&&j<m&&left[i]===right[j])ops.push(' '+left[i++]),j++;else if(i<n&&(j===m||dp[i+1][j]>=dp[i][j+1]))ops.push('-'+left[i++]);else ops.push('+'+right[j++]);}const spans=[];for(let k=0;k<ops.length;k++)if(ops[k][0]!==' '){const from=Math.max(0,k-3),to=Math.min(ops.length,k+4),last=spans.at(-1);if(last&&from<=last[1])last[1]=Math.max(last[1],to);else spans.push([from,to]);}return spans.map(([a,b])=>'@@\n'+ops.slice(a,b).join('\n')+'\n').join('');}
const patch='*** Begin Patch\n'+rows.map(r=>'*** Update File: '+site+'/'+r.path+'\n'+diff(fs.readFileSync(site+'/'+r.path,'utf8'),r.after)).join('')+'*** End Patch';
fs.writeFileSync(stage+'/ADMISSION_PATCH_COMPACT.json',JSON.stringify({at:new Date().toISOString(),rows,patch,previewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({paths:rows.map(r=>r.path)}));
